script:
test("weighted grade points and credits round the halfway result 3.125 to 3.12", function () {
  assert.deepEqual(code.calculateGpa({ courses: [{ gradePoints: "3.7", credits: "3" }, { gradePoints: "3.3", credits: "3" }, { gradePoints: "2.0", credits: "2" }] }), { gpa: "3.12" });
});

test("exact decimal half even rounds 2.675 to 2.68", function () {
  assert.deepEqual(code.calculateGpa({ courses: [{ gradePoints: "4.0", credits: "1" }, { gradePoints: "3.0", credits: "1" }, { gradePoints: "2.0", credits: "1" }, { gradePoints: "1.7", credits: "1" }] }), { gpa: "2.68" });
});

test("a value one step below halfway rounds to 2.67", function () {
  assert.deepEqual(code.calculateGpa({ courses: [{ gradePoints: "2.674", credits: "1" }] }), { gpa: "2.67" });
});

test("a value one step above halfway rounds to 2.68", function () {
  assert.deepEqual(code.calculateGpa({ courses: [{ gradePoints: "2.676", credits: "1" }] }), { gpa: "2.68" });
});

test("an empty course list returns null and does not error", function () {
  assert.deepEqual(code.calculateGpa({ courses: [] }), { gpa: null });
});

test("a single course with zero credits returns null", function () {
  assert.deepEqual(code.calculateGpa({ courses: [{ gradePoints: "3.7", credits: "0" }] }), { gpa: null });
});

test("a single course with one credit returns 4.00", function () {
  assert.deepEqual(code.calculateGpa({ courses: [{ gradePoints: "4", credits: "1" }] }), { gpa: "4.00" });
});

test("zero grade points with positive credits returns 0.00", function () {
  assert.deepEqual(code.calculateGpa({ courses: [{ gradePoints: "0", credits: "1" }] }), { gpa: "0.00" });
});

test("only the final quotient is rounded so 1.6145 becomes 1.61", function () {
  assert.deepEqual(code.calculateGpa({ courses: [{ gradePoints: "1.115", credits: "1" }, { gradePoints: "2.114", credits: "1" }] }), { gpa: "1.61" });
});

test("a zero credit course first does not void the gpa", function () {
  assert.deepEqual(code.calculateGpa({ courses: [{ gradePoints: "9.9", credits: "0" }, { gradePoints: "4.0", credits: "1" }, { gradePoints: "2.0", credits: "3" }] }), { gpa: "2.50" });
});

test("a zero credit course in the middle does not void the gpa", function () {
  assert.deepEqual(code.calculateGpa({ courses: [{ gradePoints: "4.0", credits: "1" }, { gradePoints: "9.9", credits: "0" }, { gradePoints: "2.0", credits: "3" }] }), { gpa: "2.50" });
});

test("a zero credit course last does not void the gpa", function () {
  assert.deepEqual(code.calculateGpa({ courses: [{ gradePoints: "4.0", credits: "1" }, { gradePoints: "2.0", credits: "3" }, { gradePoints: "9.9", credits: "0" }] }), { gpa: "2.50" });
});

test("an unknown field on a middle course throws unknown field note", function () {
  assert.throws(function () {
    code.calculateGpa({ courses: [{ gradePoints: "4", credits: "1" }, { gradePoints: "3", credits: "1", note: "x" }, { gradePoints: "2", credits: "1" }] });
  }, /^unknown field: note$/);
});

test("a numeric gradePoints throws invalid decimal gradePoints", function () {
  assert.throws(function () {
    code.calculateGpa({ courses: [{ gradePoints: "4.0", credits: "1" }, { gradePoints: 1.7, credits: "1" }, { gradePoints: "2.0", credits: "1" }] });
  }, /^invalid decimal: gradePoints$/);
});

test("a fractional credit just above zero total credits returns 2.00", function () {
  assert.deepEqual(code.calculateGpa({ courses: [{ gradePoints: "2", credits: "0.5" }] }), { gpa: "2.00" });
});

test("a half even tie that carries rounds 1.995 to 2.00", function () {
  assert.deepEqual(code.calculateGpa({ courses: [{ gradePoints: "1.995", credits: "1" }] }), { gpa: "2.00" });
});
